    method constructor(someWheels as integer)
        this.wheels <- someWheels;
    endMethod

    public method Wheels() as integer
        return this.wheels;
    endMethod
endClass

class Motorcycle extends Vehicle
    method constructor()
        super.constructor(2);
    endMethod
endClass

class Car extends Vehicle
    method constructor()
        super.constructor(4);
    endMethod
endClass

algorithm CountWheels
    define kind as integer;
    define vehicle as Vehicle;
    read kind;
    if kind = 1 then
        vehicle <- new Motorcycle();
    else
        vehicle <- new Car();
    endIf
    write vehicle.Wheels();
endAlgorithm
